import{z as l,x as i,o as A,c as d,q as t,j as B,D as e,d as a,s as o,S as n,b as s}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"递归与迭代","description":"","frontmatter":{"title":"递归与迭代","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dns-recursive.md","filePath":"cs/dns-recursive.md","lastUpdated":1791063341000}'),p={name:"cs/dns-recursive.md"};function D(c,E,T,m,C,h){const r=i("Mermaid");return A(),d("div",null,[E[2]||(E[2]=t('<h1 id="递归与迭代" tabindex="-1">递归与迭代 <a class="header-anchor" href="#递归与迭代" aria-label="Permalink to &quot;递归与迭代&quot;">​</a></h1><div class="epigraph"><p>存根解析器只问一台递归服务器；递归服务器替它走完从根到权威的迭代，并把答案缓存。</p><footer>—— 据 Mockapetris, RFC 1034；Kurose and Ross 对解析模式的整理</footer></div><p><a href="/cs/dns">上一课</a>给出层次名字与「从根到权威」。本课不重画区的树。缺口是谁去问：主机上的存根几乎总把完整问题交给递归解析器；递归解析器对根、TLD、权威做<strong>迭代</strong>查询（答「去问那边」），直到得到答案或失败。本课不把记录类型表写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/dns">DNS</a> 留下解析步骤。若每台笔记本自己从根迭代，根流量与延迟都不可接受，缓存也无法共享。<a href="/cs/dhcp-nat">DHCP</a> 交出的正是递归服务器地址。递归：对客户负责完整答案；迭代：服务器之间用转介把问题推向下一级。缺口是<strong>两种查询角色</strong>，不是 HTTP。</p><p><span class="marginnote">直觉类比：递归像把事整个托给旅行社——你说目的地，它办完签证机票把票递给你；迭代像每个柜台都只说「这事归隔壁窗口管」，你得自己一间间跑。DNS 里递归服务器就是那个旅行社，对最终结果负责。</span></p><p><span class="marginnote">缓存带 TTL。权威才是该区的真相；递归缓存过期后必须再走迭代。DNSSEC 是认证，后课安全再谈，本课只钉解析路径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>存根 → 递归（递归标志）。递归若缓存命中则直接答；否则从根提示开始：问，得 NS 转介，再问，直到权威的应答。迭代服务器不替对方追问。失败：名字不存在、超时、截断改 TCP，本课不把全部 RCODE 背完。</p><p><span class="marginnote">常见误区：把转介当错误。服务器回「去问 .com 的这些 NS」不是失败应答，而是迭代的正常推进——它没有替你追问的义务。真正的失败是 NXDOMAIN（名字不存在）或超时，标志位与转介完全不同。</span></p>',10)),(A(),B(n,null,{default:e(()=>[o(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20STUB%5B%22%E5%AD%98%E6%A0%B9%22%5D%20--%3E%20REC%5B%22%E9%80%92%E5%BD%92%E8%A7%A3%E6%9E%90%E5%99%A8%22%5D%0A%20%20REC%20--%3E%20ROOT%5B%22%E9%97%AE%E6%A0%B9%E5%BE%97%E8%BD%AC%E4%BB%8B%22%5D%0A%20%20ROOT%20--%3E%20TLD%5B%22%E9%97%AE%20TLD%22%5D%0A%20%20TLD%20--%3E%20AUTH%5B%22%E9%97%AE%E6%9D%83%E5%A8%81%E5%BE%97%E7%AD%94%E6%A1%88%22%5D%0A%20%20AUTH%20--%3E%20REC%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=s("h2",{id:"机制",tabindex:"-1"},[a("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=s("p",null,[a("递归把「层次查找」收成对应用透明的一次往返（加上缓存）。它与 "),s("a",{href:"/cs/lpm"},"LPM"),a(" 不同：DNS 是应用层名字，IP 前缀是定位。端到端：解析错误会把 TCP 连到错误地址，TLS 证书名检查是后课补的真实性，本课只得到「一套记录」。")],-1)),(A(),B(n,null,{default:e(()=>[o(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E9%97%AE%E9%A2%98%EF%BC%9Awww.example.com%20%E7%9A%84%20IP%22%5D%20--%3E%20RC%5B%22%E9%80%92%E5%BD%92%E8%B7%AF%E5%BE%84%22%5D%0A%20%20Q%20--%3E%20IT%5B%22%E8%BF%AD%E4%BB%A3%E8%B7%AF%E5%BE%84%22%5D%0A%20%20RC%20--%3E%20RC1%5B%22%E5%AD%98%E6%A0%B9%E6%8A%8A%E9%97%AE%E9%A2%98%E6%95%B4%E4%B8%AA%E4%BA%A4%E7%BB%99%E9%80%92%E5%BD%92%E6%9C%8D%E5%8A%A1%E5%99%A8%EF%BC%8C%E5%8E%9F%E5%9C%B0%E7%AD%89%22%5D%0A%20%20RC1%20--%3E%20RC2%5B%22%E9%80%92%E5%BD%92%E6%9C%8D%E5%8A%A1%E5%99%A8%E6%9B%BF%E5%AE%83%E6%8C%A8%E7%BA%A7%E5%8E%BB%E9%97%AE%EF%BC%8C%E4%BA%A4%E5%9B%9E%E5%AE%8C%E6%95%B4%E7%AD%94%E6%A1%88%22%5D%0A%20%20IT%20--%3E%20IT1%5B%22%E9%97%AE%E6%A0%B9%EF%BC%9A%E5%8F%AA%E5%BE%97%E5%88%B0%E3%80%8E%E5%8E%BB%E9%97%AE%20.com%E3%80%8F%E7%9A%84%E8%BD%AC%E4%BB%8B%22%5D%0A%20%20IT1%20--%3E%20IT2%5B%22%E9%97%AE%E8%AF%A2%E8%80%85%E8%87%AA%E5%B7%B1%E6%8B%BF%E7%9D%80%E8%BD%AC%E4%BB%8B%E7%BB%A7%E7%BB%AD%E9%97%AE%E4%B8%8B%E4%B8%80%E7%BA%A7%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">数字实例：缓存命中在局域网内毫秒级完成；未命中要连根、TLD、权威至少三轮公网往返，几十到几百毫秒。一个网页引用几十个域名，全靠缓存把绝大多数查询拦在递归服务器本地——这就是递归层存在的经济学。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 DoH/DoT 当主干必选，不引入根密钥典礼。答案里到底是地址还是别的对象，下一课资源记录类型。</p><p>后课默认：存根依赖递归；递归走迭代并缓存。记录类型决定答案含义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>递归对客户负责；服务器之间迭代转介。</li><li>缓存按 TTL，真相在权威。</li><li>记录类型下一课。</li><li>出处：RFC 1034；Kurose and Ross。</li></ul>',6))])}const _=l(p,[["render",D]]);export{f as __pageData,_ as default};
